BEGIN;
-- M9.6 EKB: canonical storage transversal.error_knowledge; public.lf_error_knowledge is its read view.
-- Append only NEW codes; one existing generic handoff error is a guarded recurrence.
DO $pre$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM programacion.engineering_plan_units WHERE id=279
 AND unit_code='M9.6' AND plan_code='IG_CURATOR_VALIDATOR_REFACTOR_V2'
 AND unit_metadata#>>'{m9_6_scope_alignment_v2,runtime_obligation,status}'='UNVERIFIED')
 THEN RAISE EXCEPTION 'M96_EKB_RUNTIME_HOLD_NOT_VERIFIED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM transversal.error_knowledge WHERE codigo='ENGINEERING-SHADOW-DIFF-ADJUDICATION-PERSISTENCE-001')
 THEN RAISE EXCEPTION 'M96_EKB_CANONICAL_HANDOFF_ENTRY_NOT_FOUND'; END IF;
END $pre$;
WITH s AS (SELECT $m96data$[{"codigo":"IG-M96-BUNDLE-DIGEST-NOT-FIELD-EVIDENCE-001","categoria":"INPUT_GOVERNANCE_EKB","titulo":"Hash de paquete no adjudica divergencias por campo","descripcion":"Fallo observado durante IG_CURATOR_VALIDATOR_REFACTOR_V2/M9.6: M9.7 emitio un unico recibo ANCHORED BUNDLE_DIGEST_ONLY; difference_count=1 es un cambio de bundle, no una divergencia funcional D1-D5.","causa_raiz":"M9.7 emitio un unico recibo ANCHORED BUNDLE_DIGEST_ONLY; difference_count=1 es un cambio de bundle, no una divergencia funcional D1-D5.","patron":"Hash de paquete no adjudica divergencias por campo","prevencion":"Exigir producer VERIFIED con alcance PER_FIELD_CURRENT_CANDIDATE, cobertura comprobable y recibo por diff; prohibir zero receipts = PASS.","validacion":"Gate del recibo 0a091836-f8db-4063-965d-a02fa2fbd6d5 = BLOCKED/PRODUCER_ONLY_BUNDLE_DIGEST_OR_UNVERIFIED.","severidad":"High","lote_origen":"IG_CURATOR_VALIDATOR_REFACTOR_V2/M9.6","pr":"2191","estado":"activo","evidencia":"Gate del recibo 0a091836-f8db-4063-965d-a02fa2fbd6d5 = BLOCKED/PRODUCER_ONLY_BUNDLE_DIGEST_OR_UNVERIFIED. | supabase://private.lf_evidence_ledger_v1/0a091836-f8db-4063-965d-a02fa2fbd6d5;github://cristhianlujan/claude-persona-lf-patch/pull/2191","lifecycle_phase":"SHADOW_EVIDENCE_HANDOFF","consumer_role":["INPUT_GOVERNANCE","ENGINEERING_AGENT"],"root_cause_family":"R5_EROSION_PROCESO","detectability":"PROCESS_DEPENDENT","source_context":"M9.6/PAULO-155; technical DONE does not authorize shadow cutover","source_ref":"supabase://private.lf_evidence_ledger_v1/0a091836-f8db-4063-965d-a02fa2fbd6d5;github://cristhianlujan/claude-persona-lf-patch/pull/2191"},{"codigo":"IG-M96-M17-PLAN-ADR-SHADOW-MISBIND-001","categoria":"INPUT_GOVERNANCE_EKB","titulo":"ADR M1.7 de plan mal usado para divergencias semanticas","descripcion":"Fallo observado durante IG_CURATOR_VALIDATOR_REFACTOR_V2/M9.6: ADR DEC-INPUT-GOV-M1.7-DIVERGENCE-ADJUDICATION-001 rige drift plan/currentness y waiver, no adjudicacion funcional del shadow.","causa_raiz":"ADR DEC-INPUT-GOV-M1.7-DIVERGENCE-ADJUDICATION-001 rige drift plan/currentness y waiver, no adjudicacion funcional del shadow.","patron":"ADR M1.7 de plan mal usado para divergencias semanticas","prevencion":"Separar PLAN_AUTHORITY_DRIFT_GUARD y WAIVER_AUTHORITY del juez CONTROL_EQUIVALENCE_JUDGE; mantener runtime UNVERIFIED si no hay recibos.","validacion":"PR2196 fusionado y aplicado; contrato M9.6 distingue plan y shadow; cero decisiones humanas artificiales.","severidad":"High","lote_origen":"IG_CURATOR_VALIDATOR_REFACTOR_V2/M9.6","pr":"2196","estado":"activo","evidencia":"PR2196 fusionado y aplicado; contrato M9.6 distingue plan y shadow; cero decisiones humanas artificiales. | supabase://transversal.decision_log/DEC-INPUT-GOV-M1.7-DIVERGENCE-ADJUDICATION-001;github://cristhianlujan/claude-persona-lf-patch/pull/2196","lifecycle_phase":"AUTHORITY_BINDING","consumer_role":["INPUT_GOVERNANCE","ENGINEERING_AGENT"],"root_cause_family":"R5_EROSION_PROCESO","detectability":"PROCESS_DEPENDENT","source_context":"M9.6/PAULO-155; technical DONE does not authorize shadow cutover","source_ref":"supabase://transversal.decision_log/DEC-INPUT-GOV-M1.7-DIVERGENCE-ADJUDICATION-001;github://cristhianlujan/claude-persona-lf-patch/pull/2196"},{"codigo":"IG-M96-SHADOW-V1-TYPED-SCHEMA-EXTRA-FIELDS-001","categoria":"INPUT_GOVERNANCE_EKB","titulo":"Schema de recibo shadow v1 rechaza diferencias detalladas","descripcion":"Fallo observado durante IG_CURATOR_VALIDATOR_REFACTOR_V2/M9.6: El validador ig-shadow-receipt/v1 impide agregar field_diffs al payload de comparacion de bundles; ese esquema solo prueba hashes.","causa_raiz":"El validador ig-shadow-receipt/v1 impide agregar field_diffs al payload de comparacion de bundles; ese esquema solo prueba hashes.","patron":"Schema de recibo shadow v1 rechaza diferencias detalladas","prevencion":"Versionar contrato tipado por campo sin romper v1; no reutilizar ANCHORED ni bundles como recibos VERIFIED de adjudicaci