_raiz":"Consulta combinada de cohortes AUTH/RECOVERY/ONBOARDING termino SQLSTATE 57014 durante resolucion de referencias de diseno.","patron":"Fanout shadow multicoorte excedio statement_timeout","prevencion":"Reutilizar historial y evaluar una pantalla por llamada, ampliando ante trigger; perfilar design graph en lugar de subir timeout.","validacion":"Consulta por REC_001 id 58 / version 19 retorno 47 familias, 4 oraculos y 3 divergencias; fanout de tres cohortes timeout 57014.","severidad":"Medium","lote_origen":"IG_CURATOR_VALIDATOR_REFACTOR_V2/M9.6","pr":"","estado":"activo","evidencia":"Consulta por REC_001 id 58 / version 19 retorno 47 familias, 4 oraculos y 3 divergencias; fanout de tres cohortes timeout 57014. | supabase://programacion.fn_input_governance_shadow_evaluate_v2;supabase://programacion.fn_input_resolve_design_ref","lifecycle_phase":"SHADOW_PERFORMANCE","consumer_role":["INPUT_GOVERNANCE","ENGINEERING_AGENT"],"root_cause_family":"R5_EROSION_PROCESO","detectability":"LOUD_LATE","source_context":"M9.6/PAULO-155; technical DONE does not authorize shadow cutover","source_ref":"supabase://programacion.fn_input_governance_shadow_evaluate_v2;supabase://programacion.fn_input_resolve_design_ref"},{"codigo":"IG-M96-CLOSURE-DONE-RUNTIME-HOLD-001","categoria":"INPUT_GOVERNANCE_EKB","titulo":"DONE tecnico no autoriza cutover shadow","descripcion":"Fallo observado durante IG_CURATOR_VALIDATOR_REFACTOR_V2/M9.6: M9.6 cerro 5/5 como implementacion; cobertura runtime seguia UNVERIFIED, politica D0-D5 DECLARED_NOT_ACTIVATED, 0 decisiones humanas.","causa_raiz":"M9.6 cerro 5/5 como implementacion; cobertura runtime seguia UNVERIFIED, politica D0-D5 DECLARED_NOT_ACTIVATED, 0 decisiones humanas.","patron":"DONE tecnico no autoriza cutover shadow","prevencion":"Separar estado de ingenieria de admision funcional: exigir oraculos, recibos VERIFIED, politica actual y cero UNRESOLVED antes de cutover.","validacion":"Readback terminal: work DONE/5 de 5, runtime UNVERIFIED, production_authorized=false y gate digest BLOCKED.","severidad":"High","lote_origen":"IG_CURATOR_VALIDATOR_REFACTOR_V2/M9.6","pr":"2196","estado":"activo","evidencia":"Readback terminal: work DONE/5 de 5, runtime UNVERIFIED, production_authorized=false y gate digest BLOCKED. | supabase://programacion.engineering_plan_units/279/m9_6_scope_alignment_v2;github://cristhianlujan/claude-persona-lf-patch/pull/2196","lifecycle_phase":"ENGINEERING_CLOSURE","consumer_role":["INPUT_GOVERNANCE","ENGINEERING_AGENT"],"root_cause_family":"R5_EROSION_PROCESO","detectability":"SILENT","source_context":"M9.6/PAULO-155; technical DONE does not authorize shadow cutover","source_ref":"supabase://programacion.engineering_plan_units/279/m9_6_scope_alignment_v2;github://cristhianlujan/claude-persona-lf-patch/pull/2196"},{"codigo":"IG-M96-CONNECTOR-SAFETY-RETRY-BOUNDARY-001","categoria":"INPUT_GOVERNANCE_EKB","titulo":"Rechazo de escritura por conector no prueba creacion en Git","descripcion":"Fallo observado durante IG_CURATOR_VALIDATOR_REFACTOR_V2/M9.6: create_file/create_branch/merge y consultas SQL recibieron bloqueos intermitentes de herramienta; un archivo rechazado no aparecio en readback.","causa_raiz":"create_file/create_branch/merge y consultas SQL recibieron bloqueos intermitentes de herramienta; un archivo rechazado no aparecio en readback.","patron":"Rechazo de escritura por conector no prueba creacion en Git","prevencion":"Comprobar HEAD/archivo/PR tras rechazo; reintento unico de operacion minima permitida; nunca eludir controles con escritura directa DB.","validacion":"Tras un rechazo se comprobo archivo no creado; PR2195 y siguientes fueron fusionados por ruta Git con version exacta.","severidad":"Medium","lote_origen":"IG_CURATOR_VALIDATOR_REFACTOR_V2/M9.6","pr":"2195,2198","estado":"activo","evidencia":"Tras un rechazo se comprobo archivo no creado; PR2195 y siguientes fueron fusionados por ruta Git con version exacta. | github://cristhianlujan/claude-persona-lf-patch/pull/2195;github://cristhianlujan/claude-persona-lf-patch/pull/2198","lifecycle_phase":"CONNECTOR_EXECUTION","consumer_role":["INPUT_GOVERNANCE","ENGINEERING_AGENT"],"root_cause_family":"R5_EROSION_PROCESO","detectability":"LOUD_EARLY","source_context":"M9.6/PAULO-155; technical DONE does not authorize shadow cutover","source_ref":"github://cristhianlujan/claude-persona-lf-patch/pull/2195;github://cristhianlujan/claude-persona-lf-patch/pull/2198"},{"codigo":"IG-M96-NONMATERIAL-ASSERTION-RECORDER-001","categoria":"INPUT_GOVERNANCE_EKB","titulo":"Recorder de asercion material se aplico a readback no material","descripcion":"Fallo observado durante IG_CURATOR_VALIDATOR_REFACTOR_V2/M9.6: fn_engineering_checkpoint_assertion_record_v1 devolvio ENGINEERING_ASSERTION_CONTRACT_NOT_READY/NON_MATERIAL_CHECKPOINT en UNRESOLVED_NEGATIVE.","causa_raiz":"fn_engineering_checkpoint_assertion_record_v1 devolvio ENGINEERING_ASSERTION_CONTRACT_NOT_READY/NON_MATERIAL_CHECKPOINT en UNRESOLVED_NEGATIVE.","patron":"Recorder de asercion material se aplico a readback no material","prevencion":"Si assertion_gate=NOT_REQUIRED ejecutar readback real y transition_v1 con evidencia; solo invocar assertion_record cuando READY.","validacion":"Checkpoint 4 paso a DONE mediante transition_v1 luego de dos casos SQL BLOCKED; no hubo evidencia sintética.","severidad":"Medium","lote_origen":"IG_CURATOR_VALIDATOR_REFACTOR_V2/M9.6","pr":"2198","estado":"activo","evidencia":"Checkpoint 4 paso a DONE mediante transition_v1 luego de dos casos SQL BLOCKED; no hubo evidencia sintética. | supabase://programacion.fn_engineering_checkpoint_assertion_record_v1;github://cristhianlujan/claude-persona-lf-patch/pull/2198","lifecycle_phase":"CHECKPOINT_ASSERTION","consumer_role":["INPUT_GOVERNANCE","ENGINEERING_AGENT"],"root_cause_family":"R5_EROSION_PROCESO","detectability":"LOUD_EARLY","source_context":"M9.6/PAULO-155; technical DONE does not authorize shadow cutover","source_ref":"supabase://programacion.fn_engineering_checkpoint_assertion_record_v1;github://cristhianlujan/claude-persona-lf-patch/pull/2198"}]$m96data$::jsonb payload),
rows AS (SELECT x.* FROM s, jsonb_to_recordset(s.payload) x(codigo text,categoria text,titulo text,descripcion text,causa_raiz text,patron text,prevencion text,validacion text,severidad text,lote_origen text,pr text,estado text,evidencia text,lifecycle_phase text,consumer_role text[],root_cause_family text,detectability text,source_context text,source_ref text))
INSERT INTO transversal.error_knowledge(codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,lote_origen,pr,estado,evidencia,lifecycle_phase,consumer_role,root_cause_family,detectability,source_context,source_ref,frecuencia,primera_vez,ultima_vez)
SELECT codigo,categoria,titulo,descripcion,causa_raiz,patron,prevencion,validacion,severidad,lote_origen,pr,estado,evidencia,lifecycle_phase,consumer_role,root_cause_family,detectability,source_context,source_ref,1,clock_timestamp(),clock_timestamp() FROM rows
ON CONFLICT(codigo) DO NOTHING;
UPDATE transversal.error_knowledge
 SET frecuencia=frecuencia+1,ultima_vez=clock_timestamp(),updated_at=clock_timestamp(),
 evidencia=coalesce(evidencia,'')||E'\n[M96_HANDOFF_RECURRENCE_20261011] M9.6 found an ANCHORED bundle-digest receipt but no VERIFIED per-field adjudication; PR2195 installed read-only field probe; consumer cutover remains UNVERIFIED.'
 WHERE codigo='ENGINEERING-SHADOW-DIFF-ADJUDICATION-PERSISTENCE-001'
 AND position('[M96_HANDOFF_RECURRENCE_20261011]' in coalesce(evidencia,''))=0;
DO $check$ DECLARE n int; empty_fields int; BEGIN
 SELECT count(*) INTO n FROM public.lf_error_knowledge WHERE codigo=ANY(ARRAY['IG-M96-BUNDLE-DIGEST-NOT-FIELD-EVIDENCE-001','IG-M96-M17-PLAN-ADR-SHADOW-MISBIND-001','IG-M96-SHADOW-V1-TYPED-SCHEMA-EXTRA-FIELDS-001','IG-M96-ORACLE-COVERAGE-IS-NOT-ZERO-DIVERGENCE-001','IG-M96-NEGATIVE-PACKET-CONTRACT-FAMILY-DRIFT-001','IG-M96-MIGRATION-VERSION-COLLISION-001','IG-M96-SQL-NULL-NEGATIVE-CASE-001','IG-M96-SHADOW-MULTISCREEN-TIMEOUT-001','IG-M96-CLOSURE-DONE-RUNTIME-HOLD-001','IG-M96-CONNECTOR-SAFETY-RETRY-BOUNDARY-001','IG-M96-NONMATERIAL-ASSERTION-RECORDER-001']::text[]);
 IF n<>11 THEN RAISE EXCEPTION 'M96_EKB_CODES_COUNT_MISMATCH %',n; END IF;
 SELECT count(*) INTO empty_fields FROM public.lf_error_knowledge WHERE codigo=ANY(ARRAY['IG-M96-BUNDLE-DIGEST-NOT-FIELD-EVIDENCE-001','IG-M96-M17-PLAN-ADR-SHADOW-MISBIND-001','IG-M96-SHADOW-V1-TYPED-SCHEMA-EXTRA-FIELDS-001','IG-M96-ORACLE-COVERAGE-IS-NOT-ZERO-DIVERGENCE-001','IG-M96-NEGATIVE-PACKET-CONTRACT-FAMILY-DRIFT-001','IG-M96-MIGRATION-VERSION-COLLISION-001','IG-M96-SQL-NULL-NEGATIVE-CASE-001','IG-M96-SHADOW-MULTISCREEN-TIMEOUT-001','IG-M96-CLOSURE-DONE-RUNTIME-HOLD-001','IG-M96-CONNECTOR-SAFETY-RETRY-BOUNDARY-001','IG-M96-NONMATERIAL-ASSERTION-RECORDER-001']::text[])
 AND (nullif(prevencion,'') IS NULL OR nullif(validacion,'') IS NULL OR cardinality(consumer_role)=0 OR root_cause_family IS NULL);
 IF empty_fields<>0 THEN RAISE EXCEPTION 'M96_EKB_INCOMPLETE_ROWS %',empty_fields; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.lf_error_knowledge
 WHERE codigo='ENGINEERING-SHADOW-DIFF-ADJUDICATION-PERSISTENCE-001' AND evidencia LIKE '%[M96_HANDOFF_RECURRENCE_20261011]%')
 THEN RAISE EXCEPTION 'M96_EKB_HANDOFF_RECURRENCE_NOT_RECORDED'; END IF;
END $check$;
COMMIT;
